def compute(vars):
    securities = vars["v1"]
    exercise_price = vars["v2"]
    value = securities * exercise_price

    return {
        "value": value,
        "trace": {
            "securities": securities,
            "weighted_average_exercise_price": exercise_price,
            "value": value,
            "output_meta": {
                "currency": "USD",
                "scale": "ones",
                "unit": "currency"
            }
        }
    }
